}

fn size(o: Option<Vec<Int>>) -> Int {
    match o {
        Some(w) => len(w),
        None => 0,
    }
}

fn main() {
    let v = push(push(vec(), 1), 2);
    let o = Some(v.clone()); // Clone the vector to avoid moving it
    print(len(v));
    print(size(o));
}

