    print(str_len(p.tag))
    print(q.x)
}

struct Pair { a: Vec<Int>, b: Str }

fn main() {
    let s = Pair { a: push(push(vec(), 1), 2), b: "hello" }
    let Pair { a, b } = clone(&s)
    print(len(a))
    print(str_len(b))
    print(str_len(s.b))
}

